    .AddCookie(options =>
    {
        options.LoginPath = "/login"; // Not used for API, but required
        options.Cookie.HttpOnly = true;
        options.Cookie.SameSite = Microsoft.AspNetCore.Http.SameSiteMode.Lax;
    });

builder.Services.AddAuthorization();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();

// Protected admin endpoint
app.MapGet("/admin", () => "Welcome admin!")
   .RequireAuthorization();

// Login endpoint – signs in the user "admin"
app.MapPost("/login", async (HttpContext httpContext) =>
{
    var claims = new List<Claim>
    {
        new Claim(ClaimTypes.Name, "admin")
    };
    var claimsIdentity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
    var claimsPrincipal = new ClaimsPrincipal(claimsIdentity);

    await httpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme, claimsPrincipal);
    return Results.Ok("Logged in as admin");
});

app.Run();

